//! Replays plans_ts_vectors.json (outcomes of the real flag-off userPlanService,
//! regenerated by workPlanVectors.test.ts) through the Rust `work` ops.
use serde_json::{Map, Value, json};

use super::run_json;

fn vectors() -> Value {
    serde_json::from_str(include_str!("plans_ts_vectors.json")).expect("vectors parse")
}

fn run(op: &str, input: &Value, name: &Value) -> Value {
    let output = run_json(op, &input.to_string()).unwrap_or_else(|e| panic!("{op} {name}: {e}"));
    serde_json::from_str(&output).expect("output json")
}

#[test]
fn views_and_paths_equal_typescript() {
    let doc = vectors();
    let views = doc["views"].as_array().expect("views");
    assert!(views.len() >= 25, "every view case is recorded");
    for case in views.iter().chain(doc["paths"].as_array().expect("paths")) {
        let op = case["op"].as_str().expect("op");
        assert_eq!(run(op, &case["input"], &case["name"]), case["expected"], "{op}: {}", case["name"]);
    }
}

/// Applies the ordered steps like workRust.ts `buildWorkBody` with the test stub
/// (`sealed:<key byte>:<plaintext>`), recording the encryption call order.
fn assemble(case: &Value, request: &Value) -> (Value, Vec<Value>) {
    let expected_body = &case["expected"]["body"];
    let mut body = Map::new();
    let mut calls = Vec::new();
    for step in request["steps"].as_array().expect("steps") {
        let name = step[0].as_str().expect("step name");
        let action = &step[1];
        let mut seal = |text: &str, role: &Value| {
            let byte = &case["keys"][role.as_str().expect("key role")];
            calls.push(json!([text, byte]));
            json!(format!("sealed:{byte}:{text}"))
        };
        let value = if let Some(value) = action.get("value") {
            value.clone()
        } else if let Some(text) = action.get("encrypt") {
            seal(text.as_str().expect("plaintext"), &action["key"])
        } else if let Some(member) = action.get("encrypt_input") {
            let text = case["encrypt_inputs"][member.as_str().expect("member")].as_str().expect("page json");
            seal(text, &action["key"])
        } else {
            // Slots are page-made (key wrappers, the wrapped task key): taken from the TS body.
            expected_body[action["slot"].as_str().expect("slot")].clone()
        };
        body.insert(name.to_owned(), value);
    }
    (Value::Object(body), calls)
}

/// The wrapper facts must name exactly the chat/projects the TS wrappers were built for.
fn assert_wrapper_targets(case: &Value, request: &Value, member: &str) {
    let Some(wrappers) = case["expected"]["body"][member].as_array().filter(|w| !w.is_empty()) else {
        return;
    };
    let chat: Vec<Value> = wrappers.iter().filter_map(|w| w.get("hashed_chat_id").cloned()).collect();
    let expected_chat: Vec<Value> = request["wrapper_chat_id"].as_str().map(|id| json!(format!("hash:{id}"))).into_iter().collect();
    assert_eq!(chat, expected_chat, "{member} chat target: {}", case["name"]);
    let projects: Vec<Value> = wrappers.iter().filter_map(|w| w.get("hashed_project_id").cloned()).collect();
    let expected_projects: Vec<Value> = request["wrapper_project_ids"]
        .as_array()
        .expect("wrapper project ids")
        .iter()
        .map(|id| json!(format!("hash:{}", id.as_str().expect("project id"))))
        .collect();
    assert_eq!(projects, expected_projects, "{member} project targets: {}", case["name"]);
}

#[test]
fn request_bodies_equal_typescript() {
    let doc = vectors();
    let bodies = doc["bodies"].as_array().expect("bodies");
    assert!(bodies.len() >= 20, "every body case is recorded");
    for case in bodies {
        let op = case["op"].as_str().expect("op");
        let request = run(op, &case["input"], &case["name"]);
        if let Some(error) = case["expected"].get("error") {
            assert_eq!(request.get("error"), Some(error), "{op}: {}", case["name"]);
            continue;
        }
        assert_eq!(request["path"], case["expected"]["path"], "{op} path: {}", case["name"]);
        assert_eq!(request["method"], case["expected"]["method"], "{op} method: {}", case["name"]);
        let (body, calls) = assemble(case, &request);
        assert_eq!(body, case["expected"]["body"], "{op} body: {}", case["name"]);
        assert_eq!(Value::Array(calls), case["expected"]["encrypt_calls"], "{op} encryption order: {}", case["name"]);
        assert_wrapper_targets(case, &request, "key_wrappers");
        assert_wrapper_targets(case, &request, "task_key_wrappers");
    }
}

#[test]
fn unknown_ops_and_malformed_inputs_are_refused() {
    assert_eq!(run_json("planNothing", "{}").unwrap_err(), "unknown_op:planNothing");
    assert_eq!(run_json("teamNothing", "{}").unwrap_err(), "unknown_op:teamNothing");
    assert_eq!(run_json("planView", "{}").unwrap_err(), "missing_field:record");
    assert!(run_json("planView", "not json").is_err());
    let missing_plaintext = json!({ "record": { "encrypted_title": "c" }, "fields": {} });
    assert_eq!(run_json("planView", &missing_plaintext.to_string()).unwrap_err(), "missing_field:fields.encrypted_title");
}

#[test]
fn child_collection_paths_and_wrapper_body_equal_typescript() {
    let doc: Value = serde_json::from_str(include_str!("plan_children_ts_vectors.json")).expect("child vectors parse");
    let paths = doc["paths"].as_array().expect("paths");
    assert_eq!(paths.len(), 10, "every collection is recorded for both ids");
    for case in paths {
        assert_eq!(run("planChildPath", &case["input"], &case["name"]), case["expected"], "{}", case["name"]);
    }
    for case in doc["bodies"].as_array().expect("bodies") {
        let request = run("planKeyWrappersAddBody", &case["input"], &case["name"]);
        assert_eq!(request["path"], case["expected"]["path"], "path: {}", case["name"]);
        assert_eq!(request["method"], case["expected"]["method"], "method: {}", case["name"]);
        assert_eq!(request["steps"], json!([["key_wrappers", { "value": case["input"]["key_wrappers"] }]]), "steps: {}", case["name"]);
        assert_eq!(case["expected"]["body"], json!({ "key_wrappers": case["input"]["key_wrappers"] }));
    }
    let bad = json!({ "plan_id": "p", "collection": "complete" });
    assert_eq!(run_json("planChildPath", &bad.to_string()).unwrap_err(), "bad_field:collection");
}
